sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float3x3 orient;
uniform float rotX;
uniform float rotY;
uniform float rotZ;
uniform float depth;
layout(color) uniform half4 interior;
uniform float2 position;
uniform float scale;
uniform float perspective;
uniform float shading;
uniform float light;
uniform float shine;
uniform float shadingType;
uniform float ambient;
uniform float spec;
layout(color) uniform half4 lightColor;
uniform float2 lightDir;
uniform float lightDepth;
uniform float interiorBlend;
layout(color) uniform half4 fadeColor;
uniform float fadeBlend;
uniform float widthRatio;
uniform float heightRatio;
uniform float strength;

const float PI = 3.14159265;

float3x3 turn() {
    float3 a = radians(float3(rotX, rotY, rotZ));
    float cx = cos(a.x), sx = sin(a.x), cy = cos(a.y), sy = sin(a.y), cz = cos(a.z), sz = sin(a.z);
    return float3x3(cz, -sz, 0.0, sz, cz, 0.0, 0.0, 0.0, 1.0) * float3x3(cy, 0.0, sy, 0.0, 1.0, 0.0, -sy, 0.0, cy) *
        float3x3(1.0, 0.0, 0.0, 0.0, cx, -sx, 0.0, sx, cx);
}

float4 pic(float2 uv) {
    return float4(image.eval(clamp(uv * size, float2(0.5), max(size - 0.5, float2(0.5)))));
}

float4 inside() { return float4(interior.rgb * interior.a, interior.a); }

float2 cover(float2 uv, float2 face) {
    float r = (face.x / max(face.y, 0.0001)) / (size.x / max(size.y, 0.0001));
    return (uv - 0.5) * (r > 1.0 ? float2(1.0, 1.0 / r) : float2(r, 1.0)) + 0.5;
}

float alpha(float2 q, float2 h) { return pic(q / h * 0.5 + 0.5).a; }

float3 lightAt(float3 p) {
    if (abs(lightDir.x) + abs(lightDir.y) > 0.0001) {
        float3 lp = float3(lightDir.x * 0.5, -lightDir.y * 0.5, -lightDepth * 2.0);
        return shadingType > 0.5 && shadingType < 1.5 ? normalize(lp - p) : normalize(lp);
    }
    // Keep old projects that only used the Light Angle control working.
    float a = radians(light);
    return normalize(float3(cos(a), -sin(a), -1.2));
}

float4 shade(float4 c, float3 n, float3 p, float dz) {
    if (shadingType < 0.5) return float4(min(c.rgb, float3(c.a)), c.a);
    if (shadingType > 2.5 && shadingType < 3.5) return float4(float3(dz), c.a);
    if (shadingType > 3.5 && shadingType < 4.5) return float4(n * 0.5 + 0.5, c.a);
    if (shadingType > 4.5) return float4((n * 0.5 + 0.5) * dz, c.a);
    float3 l = lightAt(p);
    float lambert = max(dot(n, l), 0.0);
    float3 surface = c.rgb * ambient + c.rgb * lightColor.rgb * lambert * (1.0 - ambient);
    surface *= shading;
    float s = shine * pow(lambert, max(spec, 1.0));
    surface = mix(surface * (1.0 - shine * 0.1), float3(1.0), s);
    return float4(min(surface, float3(c.a)), c.a);
}

half4 main(float2 coord) {
    float side = min(size.x, size.y);
    float unit = max(side * 0.5 * scale, 0.5);
    float3 h = float3(max(widthRatio, 0.01) * size.x / side, max(heightRatio, 0.01) * size.y / side, depth);
    float rb = length(h);
    float dist = max(2.0 + 40.0 * pow(1.0 - clamp(perspective, 0.0, 1.0), 3.0), rb + 0.5);
    float3 rw = normalize(float3((coord - size * 0.5 - position) / unit, dist));
    float3 ow = float3(0.0, 0.0, -dist);
    float b = dot(ow, rw);
    float disc = b * b - dot(ow, ow) + rb * rb;
    if (disc <= 0.0) return half4(0.0);
    float3x3 m = orient * turn();
    float3 ro = ow * m;
    float3 rd = rw * m;
    float3 inv = 1.0 / max(abs(rd), float3(0.000001)) * sign(rd + 0.0000001);
    float3 t1 = (-h - ro) * inv;
    float3 t2 = (h - ro) * inv;
    float3 lo = min(t1, t2);
    float3 hi = max(t1, t2);
    float t0 = max(max(lo.x, lo.y), max(lo.z, 0.0));
    float tEnd = min(hi.x, min(hi.y, hi.z));
    if (t0 >= tEnd) return half4(0.0);
    float dt = (tEnd - t0) / 64.0;
    float t = t0;
    float peak = 0.0;
    float tp = t0;
    bool hit = false;
    float hitLevel = 0.52 - 0.2 * clamp(strength, 0.0, 1.0);
    for (int i = 0; i <= 64; i++) {
        t = t0 + dt * float(i);
        float a = alpha((ro + rd * t).xy, h.xy);
        if (a > peak) { peak = a; tp = t; }
        if (a > hitLevel) { hit = true; break; }
    }
    if (!hit && peak < 0.02) return half4(0.0);
    if (hit) {
        float lo2 = max(t - dt, t0);
        float hi2 = t;
        for (int i = 0; i < 6; i++) {
            float mid = 0.5 * (lo2 + hi2);
            if (alpha((ro + rd * mid).xy, h.xy) > hitLevel) hi2 = mid; else lo2 = mid;
        }
        t = hi2;
    } else {
        t = tp;
    }
    float3 p = ro + rd * t;
    float e = 1.5 / unit;
    float4 c;
    float3 n;
    float dz = clamp((p.z + h.z) / max(2.0 * h.z, 0.0001), 0.0, 1.0);
    if (abs(p.z) > h.z - max(dt * abs(rd.z) * 1.5, 0.0005)) {
        float4 s = pic(p.xy / h.xy * 0.5 + 0.5);
        c = float4(s.rgb / max(s.a, 0.0001), 1.0);
        n = float3(0.0, 0.0, sign(p.z));
    } else {
        float2 g = float2(alpha(p.xy + float2(e, 0.0), h.xy) - alpha(p.xy - float2(e, 0.0), h.xy),
                          alpha(p.xy + float2(0.0, e), h.xy) - alpha(p.xy - float2(0.0, e), h.xy));
        n = length(g) > 0.0001 ? float3(-normalize(g), 0.0) : float3(0.0, 0.0, -1.0);
        float4 textured = pic(p.xy / h.xy * 0.5 + 0.5);
        c = mix(textured, inside(), clamp(interiorBlend, 0.0, 1.0));
        if (fadeBlend > 0.0) c.rgb = mix(c.rgb, fadeColor.rgb * c.a, clamp(fadeBlend, 0.0, 1.0) * dz);
    }
    c = shade(c, normalize(m * n), p, dz);
    return half4(hit ? c : c * min(peak * 2.0, 1.0));
}
